// Reuse the existing study shell: same navigation, deck panel and compact dock.
Object.assign(scenarioLabels,{loaded:'Guida disponibile',historical:'Guida precedente',legacy:'Guida senza fasi',error:'Analisi interrotta',loading:'Aggiornamento in corso',empty:'Nessuna guida',long:'Guida lunga',limited:'Dati avversari incompleti'});
state.theme='tactical';state.view=viewLabels[params.get('view')]?params.get('view'):'matchup';state.phase=0;
if(scenarioLabels[params.get('state')])state.scenario=params.get('state');
toolbar=function(){return `<div class="preview-toolbar"><div class="preview-intro"><span class="preview-kicker">POKÉGURU / RIFINITURA</span><strong>Matchup, stesso spazio di lavoro</strong></div><span class="fixture-note">Studio di presentazione · contenuti illustrativi</span><label class="scenario-control">Stato<select id="scenario">${Object.entries(scenarioLabels).map(([key,label])=>`<option value="${key}" ${state.scenario===key?'selected':''}>${label}</option>`).join('')}</select></label></div>`};
const phases=[
 {label:'Apertura',title:'Prepara la ricerca e una seconda linea',text:'Costruisci una linea iniziale senza impegnare subito tutte le risorse. Tieni un’alternativa se il tuo attaccante viene messo KO prima del previsto.',points:['Valuta quali carte ti servono per proseguire al turno successivo.','Prima di usare una risorsa di ricerca, considera cosa rimarrebbe disponibile.']},
 {label:'Sviluppo',title:'Scegli quali risorse impegnare',text:'Valuta ogni scambio insieme al turno che viene dopo. Una giocata utile adesso può lasciare poche opzioni per ricostruire il piano.',points:['Rivedi le alternative prima di impegnare l’ultima risorsa di recupero.','Usa la lista avversaria come riferimento, considerando che potresti incontrare una variante diversa.']},
 {label:'Chiusura',title:'Prepara il turno decisivo',text:'Individua le carte necessarie per chiudere e considera una seconda possibilità se la prima linea non è disponibile.',points:['Conta i Premi ancora necessari e verifica il bersaglio del prossimo attacco.','Conserva le risorse che rendono possibile la linea alternativa.']}
];
function phaseContent(phase,index){return `<section class="phase-panel" id="phase-panel-${index}" role="tabpanel" aria-labelledby="phase-tab-${index}" ${state.phase===index?'':'hidden'}><h3>${phase.title}</h3><p>${phase.text}</p><ul>${phase.points.map(p=>`<li>${p}</li>`).join('')}</ul>${state.scenario==='long'?Array.from({length:5},()=>'<p>Se la linea iniziale cambia, rivaluta le risorse rimaste e le alternative disponibili prima del turno successivo.</p>').join(''):''}</section>`}
matchupView=function(){
 const historical=state.scenario==='historical';
 const intro=pageIntro('','Matchup','Mega Absol / Mega Audino');
 const chooser=`<div class="view-actions"><button class="selector-button"><span><strong>Gardevoir ex</strong><small>Guida ${historical?'su v1 · lista precedente':'su v1'}</small></span>${icon('chevron')}</button><button class="secondary-button">Aggiorna metagame</button></div>`;
 if(state.scenario==='empty')return `${intro}${chooser}<section class="surface empty-state"><h2>Prepara questo matchup</h2><p>Crea un piano di gioco a partire dalla tua lista e dai dati disponibili sull’avversario.</p><button class="primary-button" data-refine="generate">Genera guida</button><details><summary>Dati da inviare e opzioni AI</summary><p>Lista principale, vincoli e dati disponibili sull’avversario. Le preferenze AI del progetto sono già selezionate.</p></details></section>`;
 return `${intro}${chooser}${historical?'<div class="refine-status"><p><b>La tua lista è cambiata.</b><br>Questa guida riguarda v1. La lista attuale è v2.</p><button class="secondary-button" data-refine="generate">Aggiorna per v2</button></div>':''}${state.scenario==='error'?'<div class="refine-status" role="alert"><p><b>Non è stato possibile aggiornare la guida.</b><br>La versione precedente è ancora disponibile.</p><button class="secondary-button" data-refine="generate">Riprova</button></div>':''}
 <section class="surface guide"><div class="guide-top"><div><span class="eyebrow">Contro Gardevoir ex</span><h2>Piano di gioco</h2></div><span class="guide-version">Revisione 2 · 26 ott</span></div>
 ${state.scenario==='legacy'?`<div class="legacy-plan"><h3>La tua guida salvata</h3><p>${phases.map(p=>p.text).join(' ')}</p><p class="context-line">Questa guida non è divisa per fasi.</p><button class="secondary-button" data-refine="generate">Aggiorna guida</button></div>`:`<div class="phase-tabs" role="tablist" aria-label="Fasi del piano">${phases.map((p,i)=>`<button type="button" class="phase-tab" id="phase-tab-${i}" role="tab" aria-selected="${state.phase===i}" aria-controls="phase-panel-${i}" tabindex="${state.phase===i?'0':'-1'}" data-phase="${i}">${p.label}</button>`).join('')}</div>${phases.map(phaseContent).join('')}`}
 <div class="key-card-grid"><div><span class="eyebrow">Le tue carte chiave</span><strong>Mega Absol ex · Mega Audino ex</strong></div><div><span class="eyebrow">Le carte avversarie</span><strong>Gardevoir ex · Kirlia</strong></div></div>
 ${state.scenario==='limited'?'<div class="refine-limit"><b>Lista avversaria incompleta</b><p>Mancano alcune carte della lista consultata. I riferimenti alla chiusura sono indicativi.</p></div>':''}
 <details class="sources"><summary>Fonti e dettagli</summary><p><b>Lista usata:</b> principale v1. <b>Guida:</b> revisione 2 del 26 ottobre.</p><p>In questo studio i contenuti sono illustrativi; non sono una guida competitiva verificata.</p><details><summary>Carte e liste consultate</summary><p>Nell’app: fonti, date e copertura delle evidenze della guida.</p></details><details><summary>Diagnostica AI</summary><p>Modello, ricerche eseguite, prompt, token e identificativi restano consultabili qui per approfondimento e assistenza.</p></details></details></section>
 <section class="surface revision"><div class="section-heading"><h2>Discuti la guida</h2><button class="quiet-button" data-refine="history">Revisioni precedenti</button></div><textarea id="refine-feedback" aria-label="Osservazione sulla guida" placeholder="Quale punto vuoi approfondire?"></textarea><div class="button-row"><details><summary>Dati da inviare e opzioni AI</summary><p>Guida corrente, osservazione, lista e dati pertinenti. Le preferenze globali sono già selezionate.</p></details><button class="primary-button" data-refine="generate">Aggiorna guida</button></div></section>`;
};
const baseRender=render;
render=function(){const draft=document.getElementById('refine-feedback')?.value??state.feedback??'';baseRender();state.feedback=draft;const field=document.getElementById('refine-feedback');if(field)field.value=draft;document.title='Pokéguru · rifinitura Matchup';if(state.view==='matchup'&&state.scenario==='loading'){document.querySelector('#workspace').innerHTML=pageIntro('','Matchup','Mega Absol / Mega Audino')+'<div class="refine-run" role="status">Aggiornamento della guida in corso… <button class="quiet-button" data-refine="cancel">Annulla</button></div>'+matchupView().replace(pageIntro('','Matchup','Mega Absol / Mega Audino'),'')}};
function selectPhase(index,focus=false){state.phase=(index+phases.length)%phases.length;document.querySelectorAll('[data-phase]').forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===state.phase));tab.tabIndex=i===state.phase?0:-1;document.getElementById(`phase-panel-${i}`).hidden=i!==state.phase});if(focus)document.getElementById(`phase-tab-${state.phase}`).focus()}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-phase]');if(tab)selectPhase(Number(tab.dataset.phase));const control=event.target.closest('[data-refine]');if(!control)return;if(control.dataset.refine==='cancel'){state.scenario='loaded';render();return}if(control.dataset.refine==='history'){const d=document.createElement('dialog');d.innerHTML='<h2>Revisioni precedenti</h2><p>Revisione 1 · 25 ottobre · lista v1</p><p>Il testo e le fonti originali restano associati alla revisione.</p><form method="dialog"><button class="secondary-button">Chiudi</button></form>';document.body.appendChild(d);d.addEventListener('close',()=>d.remove());d.showModal();return}const d=document.createElement('dialog');d.innerHTML='<h2>Anteprima del percorso</h2><p>Nell’app questa azione aggiorna la guida. Lo studio non invia richieste AI.</p><form method="dialog"><button class="secondary-button">Chiudi</button></form>';document.body.appendChild(d);d.addEventListener('close',()=>d.remove());d.showModal()});
document.addEventListener('keydown',event=>{if(!event.target.matches('[data-phase]'))return;const map={ArrowRight:state.phase+1,ArrowLeft:state.phase-1,Home:0,End:2};if(event.key in map){event.preventDefault();selectPhase(map[event.key],true)}});
render();
